/*
 * A390437  Numbers whose prime factorization exponents are not divisible by
 *          3.
 * https://oeis.org/A390437
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 230, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A390437: numbers whose prime factorization exponents are not
 * divisible by 3.  The sequence is generated by testing successive integers,
 * factoring them with the provided helper, and accepting those whose prime
 * exponents are all non‑multiples of 3.  Results are cached so that any
 * call order is supported. */
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/factor_u64.h"

/* static cache for memoisation */
static seq_t *cache = NULL;
static size_t cache_size = 0;
static size_t cache_cap  = 0;
static uint64_t checked_max = 0;

/* Ensure the cache contains at least \"target\" terms a(1)..a(target). */
static void ensure_cache(idx_t target)
{
    /* Grow the cache array if necessary. */
    if (cache_cap < target) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 8;
        while (new_cap < target) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = tmp;
        cache_cap = new_cap;
    }

    /* Scan integers until the required number of valid terms is found. */
    while (cache_size < target) {
        ++checked_max;                 /* next integer to test */

        /* 1 is always accepted. */
        if (checked_max == 1) {
            cache[cache_size++] = (seq_t)1;
            continue;
        }

        uint64_t pr[64], ex[64];
        size_t cnt;
        factor_u64(checked_max, pr, ex, &cnt);

        bool good = true;
        for (size_t i = 0; i < cnt; ++i) {
            if (ex[i] % 3 == 0) {       /* exponent divisible by 3 */
                good = false;
                break;
            }
        }

        if (good) {
            cache[cache_size++] = (seq_t)checked_max;
        }
    }
}

seq_t a(idx_t n)
{
    if (n < 1) return (seq_t)0;
    ensure_cache(n);
    return cache[n - 1];
}
